// src/server.ts   ->   npx tsx watch src/server.ts
import express, { type Request, type Response } from 'express';
import { z } from 'zod';

const createTodo = z.object({ title: z.string().min(1) });
type Todo = { id: number; title: string; done: boolean };

const todos: Todo[] = [];
const app = express();
app.use(express.json());

app.post('/todos', (req: Request, res: Response) => {
  const parsed = createTodo.safeParse(req.body);
  if (!parsed.success) return res.status(422).json(parsed.error.flatten());
  const todo: Todo = { id: todos.length + 1, title: parsed.data.title, done: false };
  todos.push(todo);
  res.status(201).json(todo);
});

app.listen(3000);
